import java.util.*;

class Solution {
    public boolean isSortedAndRotated(int[] nums) {
        int n = nums.length;
        int drops = 0;
        for (int i = 0; i < n; i++) {
            if (nums[i] > nums[(i + 1) % n]) { // compare with the next element, wrapping around
                drops++;
            }
        }
        return drops <= 1;
    }
}

