function isSortedAndRotated(nums) {
  // independent check: try every rotation start that follows a drop (or 0)
  const n = nums.length;
  let start = 0;
  for (let i = 1; i < n; i++) if (nums[i - 1] > nums[i]) { start = i; break; }
  for (let t = 1; t < n; t++) if (nums[(start + t - 1) % n] > nums[(start + t) % n]) return false;
  return true;
}
